boundary_test_sql:
WITH c AS MATERIALIZED(SELECT company_id,session_date,ticker FROM population_top3000_202608_202609_v1.working_d02_adig_corroborated_points_v1 UNION ALL SELECT company_id,session_date,ticker FROM population_top3000_202608_202609_v1.working_d02_sec_corroborated_points_v1),
tests AS(SELECT 'exact42' name,count(*)=42 ok FROM c UNION ALL SELECT 'unique_company_date',count(*)=count(DISTINCT(company_id,session_date)) FROM c UNION ALL SELECT 'ADIG_Aug3_not_extended',NOT EXISTS(SELECT 1 FROM c WHERE company_id='CIK:0002105139' AND session_date='2026-08-03') UNION ALL SELECT 'VMRK_Sep8_not_extended',NOT EXISTS(SELECT 1 FROM c WHERE company_id='CIK:0000906107' AND session_date='2026-09-08') UNION ALL SELECT 'VMRK_Sep10_not_extended',NOT EXISTS(SELECT 1 FROM c WHERE company_id='CIK:0000906107' AND session_date='2026-09-10') UNION ALL SELECT 'ADIG41',count(*)=41 FROM c WHERE ticker='ADIG' UNION ALL SELECT 'VMRK1',count(*)=1 FROM c WHERE ticker='VMRK')
SELECT count(*) checks,count(*) FILTER(WHERE ok IS TRUE) passed,jsonb_agg(name) FILTER(WHERE ok IS NOT TRUE) failures FROM tests;
